
import type { PricingAmountsInput } from './PricingAmountsInput.js';
import type { SettlementAmountsInput } from './SettlementAmountsInput.js';

export type BalanceTransactionInput = { /** Signed gross amount of this balance movement, before any fee. */ "amount_money"?: never; /** RFC3339 timestamp. Format: date-time. */ "available_at"?: never; "balance_transaction_id"?: never; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency"?: never; "description"?: never; /** Flint fee for this balance movement, never a provider cost passed through. Charges are positive; returned fees are negative. A payment of 5000 with a fee of 175 has a net amount of 4825. A payout reversal returning a fee of 25 reports fee_money -25. */ "fee_money"?: never; "hold_detail"?: never; "merchant_id"?: never; /** Signed net effect on your Flint balance: amount_money minus fee_money in the same currency. */ "net_money"?: never; /** RFC3339 timestamp. Format: date-time. */ "occurred_at"?: never; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed"; "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid"; "pricing_amounts": PricingAmountsInput; "refund_status": "none" | "partially_refunded" | "refunded"; "settlement_amounts": SettlementAmountsInput; "status": "open" | "closed"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "order_id"?: never; /** Flint payout containing this balance transaction. Present after the paid payout's entries are recorded. */ "payout_id"?: string; "related_balance_transaction_ids"?: never; "related_resource"?: never; "status"?: never; "type"?: never; };
